import { createContext, useState, useContext, useCallback, useMemo } from 'react'
import type { ReactNode } from 'react'

import { Link } from 'react-router'
import { Menu } from '@chakra-ui/react'


type MenuInfo = {title: string, items: {title: string, href: string}[]}[];
type RecipeInfo = {title: string, href: string}[];
/*
 メニューの作品一覧(items)とレシピ集一覧(recipes)は、同じタイミングで変化するので１つのコンテキストにまとめる
 */
type Context = {
  items: MenuInfo;
  setItemsComponent: (items: MenuInfo) => void;
  recipes: RecipeInfo;
  setRecipesComponent: (recipes: RecipeInfo) => void;
}
const MenuContext = createContext<Context>({
  items: [],
  setItemsComponent: (_items: MenuInfo) => {},
  recipes: [],
  setRecipesComponent: (_recipes: RecipeInfo) => {}
});

type Prop = {
  children: ReactNode;
}
export function MenuProvider(prop: Prop) {
  const { children } = prop;
  const [items, setItems] = useState<MenuInfo>([]);
  const [recipes, setRecipes] = useState<RecipeInfo>([]);

  const setItemsComponent = useCallback(
      (items: MenuInfo) => setItems(items)
    , [setItems]);
  const setRecipesComponent = useCallback(
      (recipes: RecipeInfo) => setRecipes(recipes)
    , [setRecipes]);
  const componentSet = useMemo(() => (
      { items: items, setItemsComponent: setItemsComponent, recipes: recipes, setRecipesComponent: setRecipesComponent }
    ), [items, setItemsComponent]);

  return (
    <MenuContext.Provider value={componentSet}>
      {children}
    </MenuContext.Provider>
  )
}

export const useMenuContext = () => useContext(MenuContext);


/** @jsxImportSource @emotion/react */
import { css } from '@emotion/react'


type MenuItemsProp = {
  menuInfo: {title: string, items: {title: string, href: string}[]}[];
}
export function MenuItems(prop: MenuItemsProp) {
  const { menuInfo } = prop;
  return (
    <Menu.Positioner>
      <Menu.Content role='navigation' css={menuStyle.content}>
        {menuInfo.flatMap((group, index, list) => [
          (
            <Menu.ItemGroup css={menuStyle.group} key={index}>
              <Menu.ItemGroupLabel>{group.title}</Menu.ItemGroupLabel>
              {group.items.map((link) => (
                <Menu.Item asChild key={link.href} value={link.title}>
                  <Link to={link.href}>{link.title}</Link>
                </Menu.Item>
              ))}
            </Menu.ItemGroup>
          ),
          (index + 1) < list.length ? (<Menu.Separator key={`${index}_1`} />) : undefined
        ])}
      </Menu.Content>
    </Menu.Positioner>
  )
}

type MenuRecipesProp = {
  menuInfo: {title: string, href: string}[];
}
export function MenuRecipes(prop: MenuRecipesProp) {
  const { menuInfo } = prop;
  return (
    <Menu.Positioner>
      <Menu.Content role='navigation' css={menuStyle.content}>
        {menuInfo.map((link) => (
           <Menu.Item asChild key={link.href} value={link.title}>
             <Link to={link.href}>{link.title}</Link>
           </Menu.Item>
         ))}
      </Menu.Content>
    </Menu.Positioner>
  )
}



const menuStyle = {
  /*
   サイト内リンクのサブメニューを表して、マウスポインターをそのリンクへと移動する際に、境界部分でhoverが外れて表示チラツキが発生。
   positioning={{ offset: { mainAxis: 0 } }}として隙間をなくしてもマウスポインターが境界を跨ぐとチラついてしまう（移動のアニメーションがあるので、表示が左右にブレる動きが付く）。
   そこで、content領域に設定されているアニメーションをfade-inのみにして、左右にブレるのを防止する。
   (animation-delayにアニメーション時間の負値を設定することで、ブレる時間をスキップできるが、chakra uiがmenuのanimationの完了時に行っているunmountが効かなくなるのでNG)
   */
  content: css`
    //animation-delay: calc(var(--chakra-durations-fast) * -1);
    animation-name: fade-in;
  `,
  group: css`
    > div {
      background: rgb(200 220 220);
    }
    > a {
      margin-left: 0.5em;
    }
  `
}

