import { useState, useCallback, useRef } from 'react'

import { Box, Dialog, CloseButton, Portal, VStack } from '@chakra-ui/react'

import { Remarks } from '~/ui/layout/item/explanation'



type PageInfoDialogProp = {
  open: boolean;
  closeDialog: () => void;
}

export const usePageInfoDialog = () => {
  const [open, setOpen] = useState<boolean>(false);
  
  const closeDialog = useCallback(() => setOpen(false), [setOpen]);
  const openDialog = useCallback(() => setOpen(true), [setOpen]);
  
  return [
    { open, closeDialog },
    openDialog
  ] as [PageInfoDialogProp, () => void];
}



export function PageInfoDialog(prop: PageInfoDialogProp) {
  const { open, closeDialog } = prop;
  // ダイアログ表示時に、注釈にfocusが当たらないように、初期focusをダイアログのcontent領域自体に設定する(initialFocusEl)
  const contentRef = useRef<HTMLDivElement>(null);
  
  return (
    <Dialog.Root
      role='dialog'
      scrollBehavior='inside'
      open={open}
      onOpenChange={(e) => e.open! || closeDialog()}
      initialFocusEl={() => contentRef.current}
      >
      <Portal>
        <Dialog.Backdrop />
        <Dialog.Positioner>
          <Dialog.Content ref={contentRef} maxWidth='42.0rem'>
            <Dialog.Header>
              <Dialog.Title>ページ情報</Dialog.Title>
            </Dialog.Header>
            <Dialog.Body>
              <VStack alignItems='stretch' gap='1'>
                <AuthorInfo />
                <PageHistory />
              </VStack>
            </Dialog.Body>
            <Dialog.CloseTrigger asChild>
              <CloseButton size='sm' />
            </Dialog.CloseTrigger>
          </Dialog.Content>
        </Dialog.Positioner>
      </Portal>
    </Dialog.Root>
  )
}


