import { useState, useCallback } from 'react'

import { Dialog, CloseButton, Portal } from '@chakra-ui/react'


type SettingsDialogProp = {
  open: boolean;
  closeDialog: () => void;
}

export const useSettingsDialog = () => {
  const [open, setOpen] = useState<boolean>(false);
  
  const closeDialog = useCallback(() => setOpen(false), [setOpen]);
  const openDialog = useCallback(() => setOpen(true), [setOpen]);
  
  return [
    { open, closeDialog },
    openDialog
  ] as [SettingsDialogProp, () => void];
}



export function SettingsDialog(prop: SettingsDialogProp) {
  const { open, closeDialog } = prop;
  
  return (
    <Dialog.Root
      role='dialog'
      scrollBehavior='inside'
      open={open}
      onOpenChange={(e) => e.open! || closeDialog()}
      >
      <Portal>
        <Dialog.Backdrop />
        <Dialog.Positioner>
          <Dialog.Content maxWidth='42.0rem'>
            <Dialog.Header>
              <Dialog.Title>ページ設定</Dialog.Title>
            </Dialog.Header>
            <Dialog.Body>
              <VideoSettingArea />
            </Dialog.Body>
            <Dialog.CloseTrigger asChild>
              <CloseButton size='sm' />
            </Dialog.CloseTrigger>
          </Dialog.Content>
        </Dialog.Positioner>
      </Portal>
    </Dialog.Root>
  )
}




import type { ReactNode } from 'react'

import { Card, Heading, Switch } from '@chakra-ui/react'

import { useVideoSettingContext, MyStrageError } from '~/settings'

import { GoMute, GoUnmute } from 'react-icons/go'


function VideoSettingArea() {
  // 現状、設定変更の際は「即時変更内容反映(保存ボタンを設けない)」とするので、変更有無の確認用のcmpSettingは使用しない
  const { setting, setSetting /*, cmpSetting*/ } = useVideoSettingContext();
  
  const changeMute = (mute: boolean) => {
    setting.mute = mute;
    const ret = setSetting(setting);
    if (ret) {
      const message = (ret === MyStrageError.Over) ? 
        'ご使用のブラウザで各ドメイン毎のストレージ容量制限が極端に低く設定されており、変更内容を保存できませんでした。\nお手数ですが、動画再生中の個別操作でのご対応をお願いします。' : 
        'ご使用のブラウザでストレージ利用が禁止されており、変更内容を保存できませんでした。\nお手数ですが、動画再生中の個別操作でのご対応をお願いします。';
      alert(message);
    }
  }
  
  return (
    <Card.Root size='md'>
      <Card.Header>
        <Heading as='h3' size='md'>ビデオ再生：</Heading>
      </Card.Header>
      <Card.Body paddingTop='0.5em'>
        <SwitchItem
          title='音声ミュート' 
          discription={<>ビデオ再生時の音声を、ミュート(無音)設定にしたい際は ON に。<br/>再生中にビデオ画面に表示される音量コントローラーでミュート解除できます。</>}
          onIcon={<GoMute />} offIcon={<GoUnmute />} 
          state={setting.mute} onStateChange={changeMute} />
      </Card.Body>
    </Card.Root>
  )
}



type SwitchItemProp = {
  title: string;
  discription: ReactNode;
  onIcon?: ReactNode;
  offIcon?: ReactNode;
  state: boolean;
  onStateChange: (state: boolean) => void;
}
function SwitchItem(prop: SwitchItemProp) {
  const { title, discription, onIcon, offIcon, state, onStateChange } = prop;
  
  return (
    <Card.Root flexDirection='row' overflow='hidden'>
      <Card.Body>
        <Card.Title mb='1'>{title}</Card.Title>
        <Card.Description fontSize='smaller'>
          {discription}
        </Card.Description>
      </Card.Body>
      <Card.Footer paddingInlineEnd='0.5em'>
        <Switch.Root 
          checked={state}
          onCheckedChange={({ checked }) => onStateChange(checked)}
          size='lg'
          colorPalette='purple'
          >
          <Switch.HiddenInput />
          <Switch.Control>
            {onIcon && offIcon && (
              <Switch.Thumb>
                <Switch.ThumbIndicator fallback={offIcon}>
                  {onIcon}
                </Switch.ThumbIndicator>
              </Switch.Thumb>
            )}
          </Switch.Control>
          <Switch.Label w='3em'>{state ? 'ON' : 'OFF'}</Switch.Label>
        </Switch.Root>
      </Card.Footer>
    </Card.Root>
  )
}
