import type { JSX } from 'react'

import { Box, IconButton, Menu, Portal, useBreakpointValue } from '@chakra-ui/react'

import { BiMenu, BiSolidChevronLeft, BiLink, BiSolidCog, BiInfoCircle } from 'react-icons/bi'

import { useMenuContext, MenuItems, MenuRecipes } from './menu'
import { usePageInfoDialog, PageInfoDialog } from './menu/pageInfo'
import { useSettingsDialog, SettingsDialog } from './menu/settings'


/** @jsxImportSource @emotion/react */
import { css } from '@emotion/react'


type Prop = {
  mode?: 'main' | 'drawer'
}
export function MyMenu(prop: Prop) {
  const { mode = 'main' } = prop;
  const MyMenuImpl = useBreakpointValue<(prop: Prop) => JSX.Element>(
                       { lgDown: MyMenuSmall, lg: ((mode === 'main') ? MyMenuExtend : MyMenuSmall) },
                       { ssr: false }) || MyMenuSmall;
  
  return (
    <MyMenuImpl {...prop} />
  )
}



function MyMenuSmall(prop: Prop) {
  const { mode = 'main' } = prop;
  const { items, recipes } = useMenuContext();
  
  const [ pageInfoDialogProp, openPageInfoDialog ] = usePageInfoDialog();
  const [ settingsDialogProp, openSettingsDialog ] = useSettingsDialog();
  
  const menuBarIconStyle = (mode === 'main') ? stylesForSmall.menuBarIconForMain : stylesForSmall.menuBarIconForDrawer;
  
  /*
   positioningの指定内容については、↓を参照
   https://floating-ui.com/docs/autoplacement
   */
  return (
    <>
      <Menu.Root positioning={{ placement: 'bottom-start' }}>
        <Menu.Trigger asChild>
          <IconButton css={menuBarIconStyle} size={(mode === 'main') ? 'md' : 'sm'} variant='ghost' aria-label='メニューアイコン。クリックでメニュー一覧を開きます'>
            <BiMenu />
          </IconButton>
        </Menu.Trigger>
        <Portal disabled={(mode === 'drawer')}>
          <Menu.Positioner>
            <Menu.Content>
              <Menu.Item value='pageInfo' onClick={() => openPageInfoDialog()}>
                <BiInfoCircle /><Box flex='1'>ページ情報</Box>
              </Menu.Item>
              <Menu.Item value='settings' onClick={() => openSettingsDialog()}>
                <BiSolidCog /><Box flex='1'>ページ設定</Box>
              </Menu.Item>
              <Menu.Separator />
              <Menu.Root positioning={{ placement: 'left-end', offset: { mainAxis: 0 } }}>
                <Menu.TriggerItem>
                  <BiSolidChevronLeft /><Box flex='1'>ページ内リンク</Box>
                </Menu.TriggerItem>
                <Portal disabled={true}>
                  <MenuItems menuInfo={items} />
                </Portal>
              </Menu.Root>
              {(mode === 'main') &&
                <>
                  <Menu.Separator />
                  <Menu.Root positioning={{ placement: 'left-end', offset: { mainAxis: 0 } }}>
                    <Menu.TriggerItem>
                      <BiSolidChevronLeft /><Box flex='1'>関連レシピ集リンク</Box>
                    </Menu.TriggerItem>
                    <Portal disabled={true}>
                      <MenuRecipes menuInfo={recipes} />
                    </Portal>
                  </Menu.Root>
                </>
              }
            </Menu.Content>
          </Menu.Positioner>
        </Portal>
      </Menu.Root>
      <PageInfoDialog {...pageInfoDialogProp} />
      <SettingsDialog {...settingsDialogProp} />
    </>
  )
}

function MyMenuExtend(_prop: Prop) {
  const { items, recipes } = useMenuContext();
  
  const [ pageInfoDialogProp, openPageInfoDialog ] = usePageInfoDialog();
  const [ settingsDialogProp, openSettingsDialog ] = useSettingsDialog();
  
  return (
    <>
      <Box css={stylesForExtend.menuArea}>
        <Box className='menu-button' onClick={openPageInfoDialog}>
          <Box as='div'>
            <BiInfoCircle /><Box>ページ情報</Box>
          </Box>
        </Box>
        <Box className='menu-button' onClick={openSettingsDialog}>
          <Box as='div'>
            <BiSolidCog /><Box>ページ設定</Box>
          </Box>
        </Box>
        <Box className='menu-button'>
          <Menu.Root positioning={{ placement: 'bottom-start', offset: { mainAxis: 0 } }}>
            <Menu.Trigger as='div'>
              <BiLink /><Box>ページ内リンク</Box>
            </Menu.Trigger>
            <Portal>
              <MenuItems menuInfo={items} />
            </Portal>
          </Menu.Root>
        </Box>
        <Box className='menu-button'>
          <Menu.Root positioning={{ placement: 'bottom-start', offset: { mainAxis: 0 } }}>
            <Menu.Trigger as='div'>
              <BiLink /><Box>関連レシピ集リンク</Box>
            </Menu.Trigger>
            <Portal>
              <MenuRecipes menuInfo={recipes} />
            </Portal>
          </Menu.Root>
        </Box>
      </Box>
      <Portal>
        <PageInfoDialog {...pageInfoDialogProp} />
        <SettingsDialog {...settingsDialogProp} />
      </Portal>
    </>
  )
}



const stylesForSmall = {
  menuBarIconForMain: css`
    box-shadow: -1px -1px 2px rgb(255 255 255 / 0.5), 1px 1px 2px rgb(0 0 0 / 0.25);
    
    @media (hover: hover) {
      &:is(:hover, [data-hover]):not(:disabled, [data-disabled]) {
        background: rgb(255 230 230 / 0.5);
      }
    }
    &:is([aria-expanded=true], [data-expanded], [data-state=expanded]) {
      background: rgb(255 230 230 / 0.5);
    }
    
    > svg {
      width: 1.6rem;
      height: 1.6rem;
      color: var(--text, #000);
      filter: drop-shadow(0 0 1px red) drop-shadow(0 0 4px white);
    }
  `,
  menuBarIconForDrawer: css`
    
    > svg {
      width: 1.2rem;
      height: 1.2rem;
      color: var(--text, #000);
    }
  `
}

const stylesForExtend = {
  menuArea: css`
    display: flex;
    flex-direction: row;
    gap: 0.25em;
    align-items: end;
    
    min-width: 36em;
    height: 80%;
    
    > .menu-button {
      display:flex;
      flex-direction: column;
      flex-grow: 1;
      align-items: center; 
      cursor: pointer;
      border-bottom: 0.2em solid rgb( 100 100 200 / 0.4);
      border-radius: 0.1em;
      background-image: url('${import.meta.env.BASE_URL}/substrate_h.jpg');
      background-repeat: repeat repeat;
      box-shadow: -1px -1px 1px rgb(255 255 255 / 0.3), 1px 1px 2px rgb(0 0 0 / 0.25);
      
      @media (hover: hover) {
        &:is(:hover, [data-hover]):not(:disabled, [data-disabled]) {
          background: rgb(255 230 230 / 0.5);
        }
      }
      &:is([aria-expanded=true], [data-expanded], [data-state=expanded]) {
        background: rgb(255 230 230 / 0.5);
      }
      
      > div {
        display:flex;
        flex-direction: row;
        gap: 5px;
        align-items: center;
        
        /* for text */
        text-shadow: 0 0 1px rgb(255 0 0 / 0.7), 0 0 3px rgb(255 255 255 / 0.5);
        /* for svg */
        filter: drop-shadow(0px 0px 1px rgb(255 0 0 / 0.7)) drop-shadow(0px 0px 3px rgb(255 255 255 / 0.5);
      }
    }
  `
}
